4. Building a Scratch Pad with useScratch
The Manual Way
A scratch interaction -- where the user drags across a surface and you track the starting point, current position, and deltas -- requires handling both mouse and touch events, computing element-relative coordinates, and tracking timing:
import { useEffect, useRef, useState } from "react";
interface ScratchState {
isScratching: boolean;
startX: number;
startY: number;
x: number;
y: number;
dx: number;
dy: number;
}
function ManualScratchPad() {
const canvasRef = useRef<HTMLDivElement>(null);
const [state, setState] = useState<ScratchState>({
isScratching: false,
startX: 0,
startY: 0,
x: 0,
y: 0,
dx: 0,
dy: 0,
});
const [lines, setLines] = useState<Array<{ x: number; y: number }>>([]);
const scratchingRef = useRef(false);
useEffect(() => {
const el = canvasRef.current;
if (!el) return;
const getRelativePos = (clientX: number, clientY: number) => {
const rect = el.getBoundingClientRect();
return {
x: clientX - rect.left,
y: clientY - rect.top,
};
};
const onMouseDown = (e: MouseEvent) => {
e.preventDefault();
const pos = getRelativePos(e.clientX, e.clientY);
scratchingRef.current = true;
setState({
isScratching: true,
startX: pos.x,
startY: pos.y,
x: pos.x,
y: pos.y,
dx: 0,
dy: 0,
});
setLines([pos]);
};
const onMouseMove = (e: MouseEvent) => {
if (!scratchingRef.current) return;
const pos = getRelativePos(e.clientX, e.clientY);
setState((prev) => ({
...prev,
dx: pos.x - prev.x,
dy: pos.y - prev.y,
x: pos.x,
y: pos.y,
}));
setLines((prev) => [...prev, pos]);
};
const onMouseUp = () => {
scratchingRef.current = false;
setState((prev) => ({ ...prev, isScratching: false }));
};
el.addEventListener("mousedown", onMouseDown);
window.addEventListener("mousemove", onMouseMove);
window.addEventListener("mouseup", onMouseUp);
return () => {
el.removeEventListener("mousedown", onMouseDown);
window.removeEventListener("mousemove", onMouseMove);
window.removeEventListener("mouseup", onMouseUp);
};
}, []);
return (
<div style={{ padding: 24 }}>
<div
ref={canvasRef}
style={{
width: 400,
height: 300,
background: "#f1f5f9",
borderRadius: 8,
cursor: "crosshair",
position: "relative",
overflow: "hidden",
}}
>
<svg
style={{ position: "absolute", inset: 0 }}
width={400}
height={300}
>
{lines.length > 1 && (
<polyline
points={lines.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke="#4f46e5"
strokeWidth={3}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
<p style={{ padding: 16, margin: 0, color: "#94a3b8" }}>
{state.isScratching ? "Drawing..." : "Draw here"}
</p>
</div>
</div>
);
}
This is already quite verbose, and it only handles mouse events -- no touch support. Adding touch means duplicating every handler for touchstart
, touchmove
, and touchend
. It also does not use requestAnimationFrame
, so rapid movements can overwhelm React's rendering.
With useScratch
useScratch
handles both mouse and touch events, computes element-relative coordinates, tracks timing, and batches state updates via requestAnimationFrame
. It returns a state object with isScratching
, x
, y
, dx
, dy
, elW
, elH
, and timestamps.
import { useScratch } from "@reactuses/core";
import { useRef, useState, useEffect } from "react";
function ScratchPad() {
const padRef = useRef<HTMLDivElement>(null);
const state = useScratch(padRef);
const [points, setPoints] = useState<Array<{ x: number; y: number }>>([]);
useEffect(() => {
if (state.isScratching && state.x !== undefined && state.y !== undefined) {
setPoints((prev) => [...prev, { x: state.x!, y: state.y! }]);
}
if (!state.isScratching) {
// Optionally clear on release
}
}, [state.isScratching, state.x, state.y]);
return (
<div style={{ padding: 24 }}>
<div
ref={padRef}
style={{
width: 400,
height: 300,
background: "#f1f5f9",
borderRadius: 8,
cursor: "crosshair",
position: "relative",
overflow: "hidden",
touchAction: "none",
}}
>
<svg
style={{ position: "absolute", inset: 0 }}
width={400}
height={300}
>
{points.length > 1 && (
<polyline
points={points.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke="#4f46e5"
strokeWidth={3}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
<div style={{ padding: 16, color: "#94a3b8", position: "relative" }}>
{state.isScratching ? (
<span>
Drawing at ({Math.round(state.x ?? 0)},{" "}
{Math.round(state.y ?? 0)}) -- delta: (
{Math.round(state.dx ?? 0)}, {Math.round(state.dy ?? 0)})
</span>
) : (
"Draw here (mouse or touch)"
)}
</div>
</div>
<button
onClick={() => setPoints([])}
style={{
marginTop: 12,
padding: "8px 16px",
background: "#e2e8f0",
border: "none",
borderRadius: 6,
cursor: "pointer",
}}
>
Clear
</button>
</div>
);
}
Touch support, requestAnimationFrame
batching, and element-relative coordinate computation are all handled by the hook. You also get callbacks via the onScratchStart
, onScratch
, and onScratchEnd
options if you prefer event-driven patterns over reactive state.
Practical example: scratch-to-reveal card
A classic scratch-to-reveal effect where the user scratches off a covering layer:
import { useScratch } from "@reactuses/core";
import { useRef, useState, useCallback } from "react";
function ScratchToReveal() {
const coverRef = useRef<HTMLDivElement>(null);
const canvasRef = useRef<HTMLCanvasElement>(null);
const [revealed, setRevealed] = useState(false);
const state = useScratch(coverRef, {
onScratch: (s) => {
const canvas = canvasRef.current;
if (!canvas || !s.x || !s.y) return;
const ctx = canvas.getContext("2d");
if (!ctx) return;
ctx.globalCompositeOperation = "destination-out";
ctx.beginPath();
ctx.arc(s.x, s.y, 20, 0, Math.PI * 2);
ctx.fill();
// Check how much has been scratched
const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
const pixels = imageData.data;
let transparent = 0;
for (let i = 3; i < pixels.length; i += 4) {
if (pixels[i] === 0) transparent++;
}
const ratio = transparent / (pixels.length / 4);
if (ratio > 0.5) {
setRevealed(true);
}
},
});
const initCanvas = useCallback((el: HTMLCanvasElement | null) => {
if (!el) return;
(canvasRef as React.MutableRefObject<HTMLCanvasElement>).current = el;
const ctx = el.getContext("2d");
if (ctx) {
ctx.fillStyle = "#94a3b8";
ctx.fillRect(0, 0, el.width, el.height);
ctx.font = "16px sans-serif";
ctx.fillStyle = "#fff";
ctx.textAlign = "center";
ctx.fillText("Scratch here!", el.width / 2, el.height / 2);
}
}, []);
return (
<div
ref={coverRef}
style={{
width: 300,
height: 150,
position: "relative",
borderRadius: 12,
overflow: "hidden",
cursor: "crosshair",
touchAction: "none",
}}
>
{/* Hidden content */}
<div
style={{
position: "absolute",
inset: 0,
background: "linear-gradient(135deg, #4f46e5, #7c3aed)",
display: "flex",
alignItems: "center",
justifyContent: "center",
color: "#fff",
fontSize: 20,
fontWeight: 700,
}}
>
You won a prize!
</div>
{/* Scratch layer */}
{!revealed && (
<canvas
ref={initCanvas}
width={300}
height={150}
style={{ position: "absolute", inset: 0 }}
/>
)}
</div>
);
}
5. Picking Colors from the Screen with useEyeDropper
The Manual Way
The EyeDropper API is relatively new and only available in Chromium-based browsers. Using it directly means checking for support, handling the async nature of the picker, and dealing with the abort signal:
import { useState, useCallback } from "react";
function ManualColorPicker() {
const [color, setColor] = useState<string | null>(null);
const [error, setError] = useState<string | null>(null);
const isSupported =
typeof window !== "undefined" && "EyeDropper" in window;
const pickColor = useCallback(async () => {
if (!isSupported) {
setError("EyeDropper API is not supported in this browser");
return;
}
try {
const dropper = new (window as any).EyeDropper();
const result = await dropper.open();
setColor(result.sRGBHex);
setError(null);
} catch (e: any) {
if (e.name !== "AbortError") {
setError(e.message);
}
}
}, [isSupported]);
return (
<div style={{ padding: 24 }}>
<button
onClick={pickColor}
disabled={!isSupported}
style={{
padding: "8px 16px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: isSupported ? "pointer" : "not-allowed",
opacity: isSupported ? 1 : 0.5,
}}
>
Pick a Color
</button>
{color && (
<div style={{ marginTop: 16, display: "flex", alignItems: "center", gap: 12 }}>
<div
style={{
width: 48,
height: 48,
borderRadius: 8,
background: color,
border: "1px solid #e2e8f0",
}}
/>
<code>{color}</code>
</div>
)}
{error && <p style={{ color: "#ef4444" }}>{error}</p>}
</div>
);
}
The boilerplate around feature detection, async handling, and error management is not terrible, but it adds up when you use it in multiple places.
With useEyeDropper
useEyeDropper
abstracts the EyeDropper API into a simple [isSupported, open]
tuple. The open
function returns a promise that resolves to { sRGBHex: string }
. If the API is not supported, isSupported
is false
and open
resolves with an empty string.
import { useEyeDropper } from "@reactuses/core";
import { useState } from "react";
function ColorPicker() {
const [isSupported, open] = useEyeDropper();
const [color, setColor] = useState<string | null>(null);
const pickColor = async () => {
const { sRGBHex } = await open();
if (sRGBHex) {
setColor(sRGBHex);
}
};
return (
<div style={{ padding: 24 }}>
{!isSupported && (
<p style={{ color: "#f59e0b" }}>
EyeDropper API is not supported in your browser.
</p>
)}
<button
onClick={pickColor}
disabled={!isSupported}
style={{
padding: "8px 16px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: isSupported ? "pointer" : "not-allowed",
opacity: isSupported ? 1 : 0.5,
}}
>
Pick Color from Screen
</button>
{color && (
<div
style={{
marginTop: 16,
display: "flex",
alignItems: "center",
gap: 12,
}}
>
<div
style={{
width: 48,
height: 48,
borderRadius: 8,
background: color,
border: "1px solid #e2e8f0",
}}
/>
<code style={{ fontSize: 18 }}>{color}</code>
</div>
)}
</div>
);
}
Clean, declarative, and the support check is always available so you can show a fallback UI in unsupported browsers.
Practical example: color palette builder
Build a palette by picking colors from anywhere on screen:
import { useEyeDropper } from "@reactuses/core";
import { useState } from "react";
function PaletteBuilder() {
const [isSupported, open] = useEyeDropper();
const [palette, setPalette] = useState<string[]>([]);
const addColor = async () => {
const { sRGBHex } = await open();
if (sRGBHex) {
setPalette((prev) =>
prev.includes(sRGBHex) ? prev : [...prev, sRGBHex]
);
}
};
const removeColor = (hex: string) => {
setPalette((prev) => prev.filter((c) => c !== hex));
};
return (
<div style={{ padding: 24 }}>
<h3>Color Palette Builder</h3>
<button
onClick={addColor}
disabled={!isSupported}
style={{
padding: "8px 20px",
background: "#4f46e5",
color: "#fff",
border: "none",
borderRadius: 6,
cursor: "pointer",
marginBottom: 16,
}}
>
+ Pick Color
</button>
<div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
{palette.map((hex) => (
<div
key={hex}
onClick={() => removeColor(hex)}
title="Click to remove"
style={{
width: 64,
height: 64,
borderRadius: 8,
background: hex,
border: "2px solid #e2e8f0",
cursor: "pointer",
display: "flex",
alignItems: "flex-end",
justifyContent: "center",
paddingBottom: 4,
}}
>
<span
style={{
fontSize: 10,
background: "rgba(255,255,255,0.8)",
borderRadius: 3,
padding: "1px 4px",
}}
>
{hex}
</span>
</div>
))}
</div>
{palette.length === 0 && (
<p style={{ color: "#94a3b8" }}>
Pick colors from anywhere on your screen to build a palette.
</p>
)}
</div>
);
}
6. Putting It All Together: An Interactive Canvas Tool
These hooks compose naturally. Here is an interactive drawing tool that combines mouse tracking, press detection, element bounding, scratch interaction, and a color picker:
import {
useMouse,
useMousePressed,
useElementBounding,
useScratch,
useEyeDropper,
} from "@reactuses/core";
import { useRef, useState, useEffect } from "react";
function InteractiveCanvasTool() {
const canvasRef = useRef<HTMLDivElement>(null);
const toolbarRef = useRef<HTMLDivElement>(null);
// Track mouse for the cursor preview
const mouse = useMouse(canvasRef);
// Detect press state for visual feedback
const [pressed] = useMousePressed(canvasRef);
// Track canvas position for absolute positioning of overlays
const canvasBounds = useElementBounding(canvasRef);
// Scratch state for drawing
const scratch = useScratch(canvasRef);
// Color picker
const [isEyeDropperSupported, openEyeDropper] = useEyeDropper();
// Drawing state
const [brushColor, setBrushColor] = useState("#4f46e5");
const [brushSize, setBrushSize] = useState(4);
const [strokes, setStrokes] = useState<
Array<{ points: Array<{ x: number; y: number }>; color: string; size: number }>
>([]);
const [currentStroke, setCurrentStroke] = useState<
Array<{ x: number; y: number }>
>([]);
// Accumulate points during a scratch
useEffect(() => {
if (scratch.isScratching && scratch.x !== undefined && scratch.y !== undefined) {
setCurrentStroke((prev) => [...prev, { x: scratch.x!, y: scratch.y! }]);
}
}, [scratch.isScratching, scratch.x, scratch.y]);
// Save stroke when scratching ends
useEffect(() => {
if (!scratch.isScratching && currentStroke.length > 1) {
setStrokes((prev) => [
...prev,
{ points: currentStroke, color: brushColor, size: brushSize },
]);
setCurrentStroke([]);
}
}, [scratch.isScratching, currentStroke, brushColor, brushSize]);
const pickColor = async () => {
const { sRGBHex } = await openEyeDropper();
if (sRGBHex) {
setBrushColor(sRGBHex);
}
};
const clearCanvas = () => {
setStrokes([]);
setCurrentStroke([]);
};
const isInsideCanvas =
!Number.isNaN(mouse.elementX) &&
mouse.elementX >= 0 &&
mouse.elementX <= (canvasBounds.width || 0) &&
mouse.elementY >= 0 &&
mouse.elementY <= (canvasBounds.height || 0);
return (
<div style={{ padding: 24, maxWidth: 700 }}>
<h2>Interactive Canvas Tool</h2>
{/* Toolbar */}
<div
ref={toolbarRef}
style={{
display: "flex",
alignItems: "center",
gap: 16,
marginBottom: 16,
padding: "12px 16px",
background: "#f8fafc",
borderRadius: 8,
flexWrap: "wrap",
}}
>
<label style={{ display: "flex", alignItems: "center", gap: 8 }}>
Color:
<input
type="color"
value={brushColor}
onChange={(e) => setBrushColor(e.target.value)}
style={{
width: 32,
height: 32,
border: "none",
borderRadius: 4,
cursor: "pointer",
}}
/>
</label>
{isEyeDropperSupported && (
<button
onClick={pickColor}
style={{
padding: "6px 12px",
background: "#e2e8f0",
border: "none",
borderRadius: 6,
cursor: "pointer",
fontSize: 13,
}}
>
Pick from Screen
</button>
)}
<label style={{ display: "flex", alignItems: "center", gap: 8 }}>
Size:
<input
type="range"
min={1}
max={20}
value={brushSize}
onChange={(e) => setBrushSize(Number(e.target.value))}
style={{ width: 100 }}
/>
<span style={{ fontSize: 13 }}>{brushSize}px</span>
</label>
<button
onClick={clearCanvas}
style={{
padding: "6px 12px",
background: "#fee2e2",
color: "#ef4444",
border: "none",
borderRadius: 6,
cursor: "pointer",
fontSize: 13,
}}
>
Clear
</button>
</div>
{/* Canvas */}
<div
ref={canvasRef}
style={{
width: "100%",
height: 400,
background: "#fff",
border: "2px solid #e2e8f0",
borderRadius: 8,
position: "relative",
overflow: "hidden",
cursor: "crosshair",
touchAction: "none",
}}
>
{/* SVG drawing surface */}
<svg
style={{ position: "absolute", inset: 0 }}
width="100%"
height="100%"
>
{/* Completed strokes */}
{strokes.map((stroke, i) => (
<polyline
key={i}
points={stroke.points.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke={stroke.color}
strokeWidth={stroke.size}
strokeLinecap="round"
strokeLinejoin="round"
/>
))}
{/* Current stroke being drawn */}
{currentStroke.length > 1 && (
<polyline
points={currentStroke.map((p) => `${p.x},${p.y}`).join(" ")}
fill="none"
stroke={brushColor}
strokeWidth={brushSize}
strokeLinecap="round"
strokeLinejoin="round"
/>
)}
</svg>
{/* Cursor preview */}
{isInsideCanvas && !pressed && (
<div
style={{
position: "absolute",
left: mouse.elementX - brushSize / 2,
top: mouse.elementY - brushSize / 2,
width: brushSize,
height: brushSize,
borderRadius: "50%",
border: `1px solid ${brushColor}`,
pointerEvents: "none",
}}
/>
)}
</div>
{/* Status bar */}
<div
style={{
marginTop: 12,
padding: "8px 16px",
background: "#f8fafc",
borderRadius: 6,
fontSize: 13,
display: "flex",
gap: 24,
color: "#64748b",
}}
>
<span>
Cursor: ({Math.round(mouse.elementX)},{" "}
{Math.round(mouse.elementY)})
</span>
<span>
Canvas: {Math.round(canvasBounds.width)} x{" "}
{Math.round(canvasBounds.height)}
</span>
<span>
State: {scratch.isScratching ? "Drawing" : pressed ? "Pressed" : "Idle"}
</span>
<span>Strokes: {strokes.length}</span>
</div>
</div>
);
}
Five hooks, each handling one responsibility:
-
useMouse
provides the cursor position for the brush preview circle -
useMousePressed
drives visual feedback and the status indicator -
useElementBounding
keeps track of the canvas dimensions for boundary checks -
useScratch
handles the actual drawing interaction with both mouse and touch -
useEyeDropper
lets the user sample colors from anywhere on screen
They share refs naturally, do not conflict, and all clean up on unmount.
